import{_ as r,o as a,c as o,ap as t}from"./chunks/framework.CuFS6FqL.js";const c=JSON.parse('{"title":"Food vouchers","description":"Quarterly Pluxee meal vouchers (€2/day, tax-exempt)—amounts, eligibility, and how payouts work for full- and part-time employees.","frontmatter":{"title":"Food vouchers","description":"Quarterly Pluxee meal vouchers (€2/day, tax-exempt)—amounts, eligibility, and how payouts work for full- and part-time employees."},"headers":[],"relativePath":"organization/human-resources/food-vouchers.md","filePath":"organization/human-resources/food-vouchers.md"}'),s={name:"organization/human-resources/food-vouchers.md"};function n(i,e,u,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/human-resources/food-vouchers.md for this page in Markdown format</div><h1 id="food-vouchers" tabindex="-1">Food vouchers <a class="header-anchor" href="#food-vouchers" aria-label="Permalink to &quot;Food vouchers&quot;">​</a></h1><p>Our employees receive food vouchers (not restaurant vouchers!) via Pluxee. The amount permitted by law (without taxes) is 2€ per day. We pay the amount via <a href="https://www.pluxee.at/arbeitnehmende/lkv/" target="_blank" rel="noreferrer">virtual cards</a> quarterly in arrears.<br> The vouchers are valid for usage in restaurants and supermarkets (see <a href="https://www.pluxee.at/merchant-finder/de-AT" target="_blank" rel="noreferrer">merchant-finder</a>).</p><p>For making the administration easier, we pay a standard amount for 18 working days per month (which is 18*2=36€; 108 per quarter), instead of the number of days actually worked (this is possible according to <a href="https://findok.bmf.gv.at/findok/volltext(suche:Standardsuche)?segmentId=c96dc3b6-d3b6-44c5-b13a-24c5b95bfd3b" target="_blank" rel="noreferrer">LStR 95a</a>). This means that we pay out the food vouchers once per quarter for the past quarter. Employees working part-time receive the aliquot amount.<br> If an employee doesn&#39;t work for a longer period of time (e.g. sick leave of several weeks), we stop paying out the food vouchers due to legal reasons.</p><p>We pay food vouchers voluntarily. There is no legal entitlement.</p><p>The payouts are initiated at <a href="https://clients.pluxee.at/" target="_blank" rel="noreferrer">https://clients.pluxee.at/</a> (Aron or Christoph).</p>',6)])])}const m=r(s,[["render",n]]);export{c as __pageData,m as default};
